/* GENERATED by _tools/emit_web.py - do not edit. Test 10, Part 1. */
IELTS.lesson({"test": 10, "part": 1, "title": "Test 10, Part 1 — the interview", "candidate": "omar", "script": [{"who": "examiner", "text": "Good morning. Come in, have a seat.", "ar": "صباح الخير. تفضّل بالدخول واجلس.", "shot": "two", "sex": "m", "voice": "piper-en_GB-alan-medium-s119", "clip": "../clips/1b2def3fa2b0b362.mp3"}, {"who": "examiner", "text": "My name is Mohamad Khorbatli. Can you tell me your full name, please?", "ar": "اسمي محمد خرباطلي. هل يمكنك أن تخبرني باسمك الكامل من فضلك؟", "shot": "two", "sex": "m", "voice": "piper-en_GB-alan-medium-s119", "clip": "../clips/c756d0707f344069.mp3"}, {"who": "candidate", "text": "Omar Daher.", "ar": "عمر ضاهر.", "shot": "candidate", "sex": "m", "voice": "piper-en_US-lessac-medium-s121", "clip": "../clips/387b622f982ba71b.mp3"}, {"who": "examiner", "text": "And what can I call you?", "ar": "وبماذا أناديك؟", "shot": "examiner", "sex": "m", "voice": "piper-en_GB-alan-medium-s119", "clip": "../clips/5085ae49113e09cf.mp3"}, {"who": "candidate", "text": "Omar is fine.", "ar": "عمر تكفي.", "shot": "candidate", "sex": "m", "voice": "piper-en_US-lessac-medium-s121", "clip": "../clips/187726b410d7e77d.mp3"}, {"who": "examiner", "text": "Thank you, Omar. Can I see your identification, please?", "ar": "شكراً لك يا عمر. هل يمكنني رؤية هويّتك من فضلك؟", "shot": "two", "sex": "m", "voice": "piper-en_GB-alan-medium-s119", "clip": "../clips/28c7982c91b80e3c.mp3"}, {"who": "candidate", "text": "Of course. Here you are.", "ar": "بالتأكيد. تفضّل.", "shot": null, "sex": "m", "voice": "piper-en_US-lessac-medium-s121", "clip": "../clips/3be79630a6da1d68.mp3"}, {"who": "examiner", "text": "Thank you. That's all fine.", "ar": "شكراً. كل شيء على ما يرام.", "shot": "examiner", "sex": "m", "voice": "piper-en_GB-alan-medium-s119", "clip": "../clips/a65ff8d3eccec277.mp3"}, {"who": "examiner", "text": "Now, in this first part I'd like to ask you some questions about yourself. Let's talk about celebrations.", "ar": "الآن، في هذا الجزء الأول أودّ أن أطرح عليك بعض الأسئلة عنك. لنتحدّث عن المناسبات.", "shot": "two", "sex": "m", "voice": "piper-en_GB-alan-medium-s119", "clip": "../clips/5a66a86c48af1a45.mp3"}, {"who": "examiner", "text": "What celebrations are important in your country?", "ar": "ما المناسبات المهمّة في بلدك؟", "shot": "examiner", "sex": "m", "voice": "piper-en_GB-alan-medium-s119", "clip": "../clips/6b63448e0ca186fc.mp3"}, {"who": "candidate", "text": "Well, as far as I'm concerned, the most important celebration is Eid. Both of them, but especially the one after Ramadan. The whole country stops for about three days and you visit everybody, in a fixed order, which everyone pretends isn't a rule and absolutely is not.", "ar": "حسناً، بالنسبة لي، أهمّ مناسبة هي العيد. كلاهما، وخاصّة الذي يأتي بعد رمضان. البلد كلّه يتوقّف نحو ثلاثة أيّام وتزور الجميع، بترتيب ثابت، يتظاهر الكلّ بأنّه ليس قاعدة وهو ليس كذلك إطلاقاً.", "shot": "candidate", "sex": "m", "voice": "piper-en_US-lessac-medium-s121", "clip": "../clips/68319e0d727003c8.mp3"}, {"who": "examiner", "text": "How do you usually celebrate?", "ar": "كيف تحتفل عادةً؟", "shot": "examiner", "sex": "m", "voice": "piper-en_GB-alan-medium-s119", "clip": "../clips/bc03927011c3e61c.mp3"}, {"who": "candidate", "text": "At my uncle's, which is where everyone goes. I would say that the main feature is food, obviously, but actually the thing I like is the morning. You're out at about seven to pray and the streets are full of people in new clothes who are all slightly embarrassed.", "ar": "عند عمّي، وهو المكان الذي يذهب إليه الجميع. أستطيع أن أقول إنّ أبرز ما فيه هو الطعام، طبعاً، لكنّ ما أحبّه في الحقيقة هو الصباح. تكون خارج البيت نحو السابعة للصلاة وتكون الشوارع مليئة بأناس في ثياب جديدة وكلّهم محرَجون قليلاً.", "shot": "candidate", "sex": "m", "voice": "piper-en_US-lessac-medium-s121", "clip": "../clips/e220bd096c984dec.mp3"}, {"who": "examiner", "text": "Do you give presents on these occasions?", "ar": "هل تقدّم هدايا في هذه المناسبات؟", "shot": "examiner", "sex": "m", "voice": "piper-en_GB-alan-medium-s119", "clip": "../clips/aa44871992c1fcf7.mp3"}, {"who": "candidate", "text": "To the children, yes, of course. Money, in an envelope, and there's a rate in Damascus that nobody has ever written down and everybody knows it. If you've got it wrong you hear about it for a year.", "ar": "للأطفال، نعم بالطبع. نقود، في مغلّف، وهناك سعر في دمشق لم يكتبه أحد يوماً والجميع يعرفونه. وإذا أخطأت فيه تسمع عن ذلك سنة كاملة.", "shot": "candidate", "sex": "m", "voice": "piper-en_US-lessac-medium-s121", "clip": "../clips/eadacc035a7e5755.mp3"}, {"who": "examiner", "text": "Have celebrations changed since you were a child?", "ar": "هل تغيّرت المناسبات منذ كنت طفلاً؟", "shot": "examiner", "sex": "m", "voice": "piper-en_GB-alan-medium-s119", "clip": "../clips/6915e0748fdc22db.mp3"}, {"who": "candidate", "text": "To a certain extent, yes. The structure is the same. What's changed is the number of people in the room, because a lot of my cousins have left Damascus now, so there's a long section of the day that's spent on video calls, with the phone propped against the fruit bowl.", "ar": "إلى حدّ ما، نعم. الهيكل نفسه. ما تغيّر هو عدد الموجودين في الغرفة، لأنّ كثيراً من أبناء عمّي غادروا دمشق الآن، فهناك جزء طويل من اليوم يُقضى في مكالمات مصوّرة، والهاتف مسنود إلى سلّة الفاكهة.", "shot": "candidate", "sex": "m", "voice": "piper-en_US-lessac-medium-s121", "clip": "../clips/bb7eb8d234f9025e.mp3"}, {"who": "examiner", "text": "Let's move on to talk about music.", "ar": "لننتقل للحديث عن الموسيقى.", "shot": "two", "sex": "m", "voice": "piper-en_GB-alan-medium-s119", "clip": "../clips/513a65b2bdce71c7.mp3"}, {"who": "examiner", "text": "Do you listen to music often?", "ar": "هل تستمع إلى الموسيقى كثيراً؟", "shot": "examiner", "sex": "m", "voice": "piper-en_GB-alan-medium-s119", "clip": "../clips/ffc60048a3782e7b.mp3"}, {"who": "candidate", "text": "Quite often, in my opinion. Well, I mean, yes, every day, mostly walking to work in Damascus.", "ar": "كثيراً نوعاً ما، في رأيي. حسناً، أعني، نعم، كلّ يوم، في معظمه وأنا ماشٍ إلى العمل في دمشق.", "shot": "candidate", "sex": "m", "voice": "piper-en_US-lessac-medium-s121", "clip": "../clips/421232edd72618f6.mp3"}, {"who": "examiner", "text": "What kind of music do you like?", "ar": "أيّ نوع من الموسيقى تحبّ؟", "shot": "examiner", "sex": "m", "voice": "piper-en_GB-alan-medium-s119", "clip": "../clips/b92466b8b7be6433.mp3"}, {"who": "candidate", "text": "Older Arabic music, mostly, I suppose, because it's the long ones, forty minutes, where the singer repeats one line about nine times and each time it's different. My friends in Damascus find this unbearable.", "ar": "الموسيقى العربيّة القديمة في معظمها، على ما أظنّ، لأنّها الطويلة، أربعون دقيقة، يعيد فيها المغنّي سطراً واحداً نحو تسع مرّات وفي كلّ مرّة يكون مختلفاً. أصدقائي في دمشق لا يطيقون هذا.", "shot": "candidate", "sex": "m", "voice": "piper-en_US-lessac-medium-s121", "clip": "../clips/487c510e1e45b11c.mp3"}, {"who": "examiner", "text": "Has your taste in music changed?", "ar": "هل تغيّر ذوقك الموسيقي؟", "shot": "examiner", "sex": "m", "voice": "piper-en_GB-alan-medium-s119", "clip": "../clips/9d0b5621a2b01010.mp3"}, {"who": "candidate", "text": "It has, yes. When I was younger I listened to whatever was popular and I would say that I didn't really choose it. Now I choose, and I'm choosing things my father listened to, which, honestly, I find slightly annoying about myself.", "ar": "تغيّر، نعم. حين كنت أصغر كنت أستمع إلى ما هو رائج وأستطيع أن أقول إنّني لم أكن أختاره فعلاً. الآن أختار، وأنا أختار أشياء كان أبي يستمع إليها، وهذا، بصراحة، أمر يزعجني قليلاً في نفسي.", "shot": "candidate", "sex": "m", "voice": "piper-en_US-lessac-medium-s121", "clip": "../clips/ad0e8b74d74d10b0.mp3"}, {"who": "examiner", "text": "Do you think music is important for young people?", "ar": "هل تظنّ أنّ الموسيقى مهمّة للشباب؟", "shot": "examiner", "sex": "m", "voice": "piper-en_GB-alan-medium-s119", "clip": "../clips/68b1d73e8e06125d.mp3"}, {"who": "candidate", "text": "Very important, in my opinion. Well, it's a way to express themselves and also to find people who are similar to them. When I was at university in Damascus you could tell which group somebody belonged to in about four seconds, and it wasn't from anything except the music.", "ar": "مهمّة جداً، في رأيي. حسناً، هي وسيلة للتعبير عن أنفسهم ولإيجاد أناس يشبهونهم أيضاً. حين كنت في الجامعة في دمشق كنت تعرف إلى أيّ مجموعة ينتمي أحدهم في أربع ثوانٍ تقريباً، ولم يكن ذلك من أيّ شيء سوى الموسيقى.", "shot": "candidate", "sex": "m", "voice": "piper-en_US-lessac-medium-s121", "clip": "../clips/262f1c74c93baf9a.mp3"}, {"who": "examiner", "text": "Finally in this part, let's talk about being on time.", "ar": "وأخيراً في هذا الجزء، لنتحدّث عن الالتزام بالمواعيد.", "shot": "two", "sex": "m", "voice": "piper-en_GB-alan-medium-s119", "clip": "../clips/a26385946d457fbb.mp3"}, {"who": "examiner", "text": "Are you usually on time?", "ar": "هل تلتزم بالمواعيد عادةً؟", "shot": "examiner", "sex": "m", "voice": "piper-en_GB-alan-medium-s119", "clip": "../clips/e45c3122989e57f6.mp3"}, {"who": "candidate", "text": "I would say that I am, yes. Well, I'm early, which is a different problem. I'll arrive at the university about fifteen minutes before everything and then stand somewhere pretending to look at my phone.", "ar": "أستطيع أن أقول نعم. حسناً، أنا أبكّر، وهذه مشكلة أخرى. أصل إلى الجامعة قبل أيّ شيء بنحو خمس عشرة دقيقة ثمّ أقف في مكان ما متظاهراً بالنظر إلى هاتفي.", "shot": "candidate", "sex": "m", "voice": "piper-en_US-lessac-medium-s121", "clip": "../clips/cb6fa9513d621318.mp3"}, {"who": "examiner", "text": "Do you think being late is rude?", "ar": "هل تظنّ أنّ التأخّر قلّة ذوق؟", "shot": "examiner", "sex": "m", "voice": "piper-en_GB-alan-medium-s119", "clip": "../clips/4d245ed8c82e2fca.mp3"}, {"who": "candidate", "text": "To a certain extent, I suppose. It depends very much on the occasion, because nobody's early to a family lunch in Damascus and nobody'd want you to be. But a job interview, obviously. The same ten minutes means two completely different things.", "ar": "إلى حدّ ما، على ما أظنّ. يتوقّف الأمر كثيراً على المناسبة، لأنّ لا أحد يبكّر إلى غداء عائلي في دمشق ولا أحد يريدك أن تبكّر. أمّا مقابلة عمل، فطبعاً. العشر دقائق نفسها تعني أمرين مختلفين تماماً.", "shot": "candidate", "sex": "m", "voice": "piper-en_US-lessac-medium-s121", "clip": "../clips/93001eae8837129d.mp3"}, {"who": "examiner", "text": "How do you usually plan your day?", "ar": "كيف تخطّط ليومك عادةً؟", "shot": "examiner", "sex": "m", "voice": "piper-en_GB-alan-medium-s119", "clip": "../clips/58413307908f79ba.mp3"}, {"who": "candidate", "text": "Badly, in my opinion. I write a list every morning before I leave for work in Damascus and I've never once finished one. At this point, honestly, the list only records what I'd meant to do, which is a different thing from a plan.", "ar": "بشكل سيّئ، في رأيي. أكتب قائمة كلّ صباح قبل أن أخرج إلى العمل في دمشق ولم أنهِ واحدة منها ولو مرّة. في هذه المرحلة، بصراحة، القائمة تسجّل فقط ما كنت أنوي فعله، وهذا شيء مختلف عن الخطّة.", "shot": "candidate", "sex": "m", "voice": "piper-en_US-lessac-medium-s121", "clip": "../clips/bd508c9c03af14fd.mp3"}, {"who": "examiner", "text": "Is being punctual important in your culture?", "ar": "هل الالتزام بالوقت مهمّ في ثقافتك؟", "shot": "examiner", "sex": "m", "voice": "piper-en_GB-alan-medium-s119", "clip": "../clips/4911b88d80fce380.mp3"}, {"who": "candidate", "text": "Less than in some, and I'd be careful about how that gets described. There's a sort of agreed flexibility. An invitation for eight in Damascus means somewhere after half past, and everyone knows it, so nobody is actually late. It's a different clock, and not a worse one.", "ar": "أقلّ مما هو في غيرها، وسأكون حذراً في كيفيّة وصف ذلك. هناك نوع من المرونة المتّفق عليها. دعوة في الثامنة في دمشق تعني ما بعد الثامنة والنصف، والجميع يعرفون ذلك، فلا أحد متأخّر فعلاً. إنّها ساعة مختلفة، وليست أسوأ.", "shot": "candidate", "sex": "m", "voice": "piper-en_US-lessac-medium-s121", "clip": "../clips/8d50b68379b40eae.mp3"}, {"who": "examiner", "text": "Thank you. That is the end of Part One.", "ar": "شكراً لك. بهذا ينتهي القسم الأول.", "shot": "two", "sex": "m", "voice": "piper-en_GB-alan-medium-s119", "clip": "../clips/50f379466faf1658.mp3"}], "boxes": [{"q": "What celebrations are important in your country?", "ar": null, "topic": "Celebrations", "model": "Well, as far as I'm concerned, the most important celebration is Eid. Both of them, but especially the one after Ramadan. The whole country stops for about three days and you visit everybody, in a fixed order, which everyone pretends isn't a rule and absolutely is not.", "modelBand": 7.0, "why": "Names the thing, then the one that matters most, then a social observation with a sting in it. The fixed order nobody admits to is the whole answer."}, {"q": "How do you usually celebrate?", "ar": null, "topic": "Celebrations", "model": "At my uncle's, which is where everyone goes. I would say that the main feature is food, obviously, but actually the thing I like is the morning. You're out at about seven to pray and the streets are full of people in new clothes who are all slightly embarrassed.", "modelBand": 7.0, "why": "Starts on the obvious answer, rejects it, and gives the real one. The embarrassment of people in new clothes is the detail a real memory supplies."}, {"q": "Do you give presents on these occasions?", "ar": null, "topic": "Celebrations", "model": "To the children, yes, of course. Money, in an envelope, and there's a rate in Damascus that nobody has ever written down and everybody knows it. If you've got it wrong you hear about it for a year.", "modelBand": 7.0, "why": "A custom with a rule, and the rule is unwritten and enforced. Three sentences and a consequence."}, {"q": "Have celebrations changed since you were a child?", "ar": null, "topic": "Celebrations", "model": "To a certain extent, yes. The structure is the same. What's changed is the number of people in the room, because a lot of my cousins have left Damascus now, so there's a long section of the day that's spent on video calls, with the phone propped against the fruit bowl.", "modelBand": 7.0, "why": "Separates what has changed from what has not, and ends on one image - the phone against the fruit bowl - rather than on a generalisation."}, {"q": "Do you listen to music often?", "ar": null, "topic": "Music", "model": "Quite often, in my opinion. Well, I mean, yes, every day, mostly walking to work in Damascus.", "modelBand": 7.0, "why": "Corrects his own hedge within one sentence, which is how a careful speaker actually answers a frequency question."}, {"q": "What kind of music do you like?", "ar": null, "topic": "Music", "model": "Older Arabic music, mostly, I suppose, because it's the long ones, forty minutes, where the singer repeats one line about nine times and each time it's different. My friends in Damascus find this unbearable.", "modelBand": 7.0, "why": "Specific, technical about the thing he loves, and funny about the cost of loving it."}, {"q": "Has your taste in music changed?", "ar": null, "topic": "Music", "model": "It has, yes. When I was younger I listened to whatever was popular and I would say that I didn't really choose it. Now I choose, and I'm choosing things my father listened to, which, honestly, I find slightly annoying about myself.", "modelBand": 7.0, "why": "Describes a change in himself and his own reaction to it. 'Annoying about myself' is exact and unforced."}, {"q": "Do you think music is important for young people?", "ar": null, "topic": "Music", "model": "Very important, in my opinion. Well, it's a way to express themselves and also to find people who are similar to them. When I was at university in Damascus you could tell which group somebody belonged to in about four seconds, and it wasn't from anything except the music.", "modelBand": 7.0, "why": "An opinion, a reason, and then four seconds at a Damascus university as evidence."}, {"q": "Are you usually on time?", "ar": null, "topic": "Being on time", "model": "I would say that I am, yes. Well, I'm early, which is a different problem. I'll arrive at the university about fifteen minutes before everything and then stand somewhere pretending to look at my phone.", "modelBand": 7.0, "why": "Answers, qualifies into something more honest, and supplies the behaviour that proves it."}, {"q": "Do you think being late is rude?", "ar": null, "topic": "Being on time", "model": "To a certain extent, I suppose. It depends very much on the occasion, because nobody's early to a family lunch in Damascus and nobody'd want you to be. But a job interview, obviously. The same ten minutes means two completely different things.", "modelBand": 7.0, "why": "Refuses a single answer and gives the rule that decides it. The same ten minutes meaning two things is the insight."}, {"q": "How do you usually plan your day?", "ar": null, "topic": "Being on time", "model": "Badly, in my opinion. I write a list every morning before I leave for work in Damascus and I've never once finished one. At this point, honestly, the list only records what I'd meant to do, which is a different thing from a plan.", "modelBand": 7.0, "why": "A confession with a daily habit behind it, ending on a distinction between a plan and a record."}, {"q": "Is being punctual important in your culture?", "ar": null, "topic": "Being on time", "model": "Less than in some, and I'd be careful about how that gets described. There's a sort of agreed flexibility. An invitation for eight in Damascus means somewhere after half past, and everyone knows it, so nobody is actually late. It's a different clock, and not a worse one.", "modelBand": 7.0, "why": "Defends a cultural difference without claiming it is better, which is the hardest version of this answer."}], "voices": {"examiner": "piper-en_GB-alan-medium-s119", "candidate": "piper-en_US-lessac-medium-s121"}});
